import { Form, useSearchParams } from "react-router";

const categories = [
  { value: "packs", label: "Packs" },
  { value: "tents", label: "Tents" },
  { value: "apparel", label: "Apparel" },
  { value: "cooking", label: "Cooking" },
];

export function ProductFilters() {
  const [searchParams, setSearchParams] = useSearchParams();
  const category = searchParams.get("category") ?? "";
  const query = searchParams.get("q") ?? "";

  function chooseCategory(next: string) {
    setSearchParams((params) => {
      if (next) params.set("category", next);
      else params.delete("category");
      params.delete("page");
      return params;
    });
  }

  return (
    <div className="filters">
      <Form role="search">
        <input type="search" name="q" defaultValue={query} aria-label="Search products" />
        {category && <input type="hidden" name="category" value={category} />}
      </Form>
      <label>
        Category
        <select value={category} onChange={(event) => chooseCategory(event.target.value)}>
          <option value="">All</option>
          {categories.map((c) => (
            <option key={c.value} value={c.value}>
              {c.label}
            </option>
          ))}
        </select>
      </label>
    </div>
  );
}

import { data, type LoaderFunctionArgs } from "react-router";
import type { Product, ProductList } from "./types";

export async function productsLoader({ request }: LoaderFunctionArgs) {
  const { search } = new URL(request.url);
  const response = await fetch(`/v1/products${search}`, { signal: request.signal });
  if (!response.ok) {
    throw data("The shop couldn't load its products.", { status: response.status });
  }
  return (await response.json()) as ProductList;
}

export async function productLoader({ params, request }: LoaderFunctionArgs) {
  const slug = params.slug ?? "";
  const response = await fetch(`/v1/products/${encodeURIComponent(slug)}`, {
    signal: request.signal,
  });
  if (response.status === 404) {
    throw data(`There's no product called ${slug}.`, { status: 404 });
  }
  if (!response.ok) {
    throw new Error(`GET /v1/products/${slug} answered ${response.status}`);
  }
  return (await response.json()) as Product;
}

import { redirect, type ActionFunctionArgs } from "react-router";

export async function loginAction({ request }: ActionFunctionArgs) {
  const form = await request.formData();
  const response = await fetch("/v1/auth/login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email: form.get("email"), password: form.get("password") }),
  });

  if (response.status === 401) {
    return { error: "That email and password don't match an account." };
  }
  if (!response.ok) {
    return { error: "Logging in didn't work. Try again in a minute." };
  }

  const next = new URL(request.url).searchParams.get("next") ?? "";
  const safeNext = next.startsWith("/") && !next.startsWith("//") ? next : "/account";
  return redirect(safeNext);
}

import { Form, useActionData, useNavigation } from "react-router";
import type { loginAction } from "./loginAction";

export function LoginPage() {
  const result = useActionData<typeof loginAction>();
  const navigation = useNavigation();
  const loggingIn = navigation.state === "submitting";

  return (
    <section>
      <title>Log in · Trailhead</title>
      <h1>Log in</h1>
      <Form method="post">
        <label>
          Email
          <input type="email" name="email" autoComplete="email" required />
        </label>
        <label>
          Password
          <input type="password" name="password" autoComplete="current-password" required />
        </label>
        {result?.error && <p role="alert">{result.error}</p>}
        <button type="submit" disabled={loggingIn}>
          {loggingIn ? "Logging in…" : "Log in"}
        </button>
      </Form>
    </section>
  );
}

import { isRouteErrorResponse, Link, useRouteError } from "react-router";

export function ProductErrorBoundary() {
  const error = useRouteError();
  if (!isRouteErrorResponse(error) || error.status !== 404) throw error;

  return (
    <section>
      <title>Product not found · Trailhead</title>
      <h1>We couldn't find that product</h1>
      <p>{error.data}</p>
      <Link to="/products">See everything in the shop</Link>
    </section>
  );
}

import { redirect, type MiddlewareFunction } from "react-router";
import { userContext, type User } from "./userContext";

export const requireUser: MiddlewareFunction = async ({ request, context }) => {
  const response = await fetch("/v1/me", { signal: request.signal });

  if (response.status === 401) {
    const { pathname, search } = new URL(request.url);
    throw redirect(`/login?next=${encodeURIComponent(pathname + search)}`);
  }
  if (!response.ok) {
    throw new Error(`GET /v1/me answered ${response.status}`);
  }

  context.set(userContext, (await response.json()) as User);
};

